// Question pool 12: identity and access in depth (IAM, federation, Organizations, Cognito, secrets). Exam level. Data only; ids key saved stats, never rename or reuse.
window.QUIZ.push(

// ---------- IAM policies: evaluation, boundaries, session policies, conditions, tags, Access Analyzer ----------

{id:"q12-001", day:12, dom:1, tags:["IAM policies"],
 q:"A company keeps monthly finance exports in an S3 bucket named <code>finance-exports</code>. An auditor works as an IAM user in the same AWS account. The user has no permissions boundary, the user's only identity-based policy allows read access to Amazon CloudWatch and nothing in Amazon S3, and no policy that applies to the user contains a Deny statement. A security engineer adds a statement to the bucket policy that allows <code>s3:GetObject</code> on the bucket's objects with the auditor's IAM user ARN as the principal. What happens when the auditor downloads an object from the bucket?",
 o:["The download fails, because the user's identity-based policy must also allow <code>s3:GetObject</code> on the bucket.",
    "The download succeeds, because in the same account an Allow in the bucket policy that names the user is enough.",
    "The download fails, because an identity-based policy that does not mention Amazon S3 acts as an explicit deny.",
    "The download succeeds only after the auditor assumes an IAM role that the bucket policy names as well."],
 a:[1],
 x:["Both sides must allow a request only when it crosses accounts. Inside one account, an Allow in either the identity-based policy or the resource-based policy is enough for most resources.",
    "Within a single account, a resource-based policy that grants permission directly to an IAM user ARN is not limited by an implicit deny in the user's identity-based policy. With no explicit Deny anywhere, the request is allowed.",
    "A policy that is silent about an action is an implicit deny, which an applicable Allow overrides. Only a statement with the Deny effect is an explicit deny.",
    "No role is involved: the bucket policy grants the access to the IAM user itself, so the user's own credentials are sufficient."],
 ref:["d4c1"], doc:"iam-policy-eval"},

{id:"q12-002", day:12, dom:1, tags:["IAM policies"],
 q:"A platform team lets developers create IAM roles for their applications, but every role must carry the permissions boundary <code>AppBoundary</code>, which allows all Amazon S3, Amazon SQS and Amazon DynamoDB actions. A developer creates a role with that boundary and attaches one identity-based policy that allows <code>sqs:SendMessage</code> and <code>sqs:ReceiveMessage</code> on the application's queue. The application can use the queue but gets AccessDenied when it reads an object from the team's S3 bucket in the same account. The bucket has no bucket policy, and the boundary must stay in place unchanged. What should the developer do so that the application can read the objects?",
 o:["Add a statement that allows <code>s3:GetObject</code> on the bucket's objects to the <code>AppBoundary</code> policy.",
    "Remove <code>AppBoundary</code> from the role so that the permissions that it lists take effect for the application.",
    "Add the Amazon S3 service principal to the role's trust policy so that S3 accepts the role's requests.",
    "Add a statement that allows <code>s3:GetObject</code> on the bucket's objects to the role's identity-based policy."],
 a:[3],
 x:["The boundary already allows every S3 action, and it must stay unchanged. A boundary limits permissions but does not provide permissions on its own.",
    "Removing the boundary breaks the team's rule and would not help: the role would be left with only its SQS permissions, because the boundary never granted anything.",
    "A trust policy defines who can assume the role, not what the role may do. Trusting Amazon S3 gives the application no S3 permissions.",
    "A permissions boundary only sets the maximum that identity-based policies can grant. The role can perform only the actions that both its identity-based policy and its boundary allow, so the S3 action must be allowed in the identity-based policy."],
 ref:[], doc:"iam-boundaries"},

{id:"q12-003", day:12, dom:1, tags:["IAM policies"],
 q:"A SaaS company runs a document service for 3,000 customers in one AWS account. All documents are in one S3 bucket under a prefix per customer. The backend assumes a single IAM role, <code>DocAccess</code>, whose policy allows reading and writing the whole bucket, and then acts for whichever customer made the request. After a bug let one customer's request read another customer's prefix, the security team requires that the temporary credentials used for a request can reach only that customer's prefix. The company does not want to create and maintain an IAM role per customer. Which solution meets these requirements?",
 o:["Pass a session policy that allows only the customer's prefix each time the backend calls <code>AssumeRole</code> for a request.",
    "Attach a permissions boundary to <code>DocAccess</code> that lists every customer prefix that the role may use.",
    "Add every customer prefix as a separate statement to the identity-based policy of the <code>DocAccess</code> role.",
    "Create an IAM user per customer with a policy for its prefix, and store the access keys with the backend."],
 a:[0],
 x:["A session policy passed to <code>AssumeRole</code> limits that one session to the intersection of the role's identity-based policy and the session policy. Each request's credentials are confined to one prefix while a single role serves every customer.",
    "A boundary is fixed on the role and applies in the same way to every session, so each session could still reach all the prefixes that the boundary lists.",
    "Listing the prefixes one by one grants the same access as before: every session of the role can still read every customer's prefix.",
    "Thousands of IAM users are more to maintain than the roles the company ruled out, and they bring long-term access keys, where AWS recommends temporary credentials from roles for workloads."],
 ref:[], doc:"iam-policies"},

{id:"q12-004", day:12, dom:1, tags:["IAM policies"],
 q:"A company uses attribute-based access control in one AWS account. Each developer assumes a role that is tagged with a <code>team</code> value, and one shared policy allows reading and changing resources only when the resource's <code>team</code> tag equals the principal's <code>team</code> tag. The same policy allows the tagging and untagging actions on all resources so that developers can label what they create. A review finds that a developer on the payments team changed the <code>team</code> tag of a resource that belongs to the analytics team and then read it. The company wants to keep the single shared policy. Which change closes this gap?",
 o:["Replace the shared policy with one policy per team that lists the ARNs of all the resources that belong to that team.",
    "Add a permissions boundary to every developer role that allows only the AWS services that the developers work with.",
    "Allow tagging only when the resource's <code>team</code> tag and any <code>team</code> tag in the request match the principal's tag.",
    "Require MFA for the read actions by adding an <code>aws:MultiFactorAuthPresent</code> condition to the shared policy."],
 a:[2],
 x:["This closes the gap but gives up the single policy: resource lists per team must be edited whenever a resource is created, which is the maintenance that ABAC removes.",
    "A boundary that allows the same services still allows the tagging actions on every resource, so a developer could still re-tag another team's resource and then read it.",
    "With ABAC the tags are the permissions, so the tagging actions need the same guard: a condition that <code>aws:ResourceTag/team</code> matches <code>aws:PrincipalTag/team</code>, and that any <code>aws:RequestTag/team</code> carries the principal's own value. The AWS ABAC tutorial also denies removing the access tags.",
    "MFA shows how the developer signed in. It does not change what the tag comparison allows: after re-tagging, the read still matches the policy."],
 ref:[], doc:"iam-abac"},

{id:"q12-005", day:12, dom:1, tags:["IAM policies"],
 q:"A company's developers write their own customer managed IAM policies and deploy them through a CI/CD pipeline. A security review found policies with statements that never took effect because of syntax mistakes, and others that AWS would consider overly permissive. A further problem: an edit to an existing policy sometimes grants access that the previous version did not, without anyone noticing. The security team wants both problems caught automatically in the pipeline before a policy is deployed. Which combination of actions meets these requirements with the LEAST operational overhead? (Choose two.)",
 o:["Run IAM Access Analyzer policy validation on each policy document, and stop the pipeline on errors and security warnings.",
    "Create an IAM Access Analyzer external access analyzer for the account, and review its findings before each deployment.",
    "Download the IAM credential report in the pipeline, and compare it with the report from the previous deployment.",
    "Run an IAM Access Analyzer custom policy check for new access that compares each updated policy with its existing version.",
    "Generate each policy with IAM Access Analyzer from the CloudTrail activity of the developer who wrote the policy."],
 a:[0,3],
 x:["Policy validation checks a policy document against IAM policy grammar and AWS best practices and returns errors, security warnings, general warnings and suggestions with recommendations. It is available in the AWS CLI and API, so a pipeline can call it.",
    "An external access analyzer reports resources that are already shared with principals outside the zone of trust. It does not check the grammar of a policy document that has not been deployed.",
    "The credential report lists the account's users and the status of their passwords, access keys and MFA devices. It says nothing about the content of policies.",
    "The custom policy check for new access (<code>CheckNoNewAccess</code> in the API) tells whether an updated policy grants new access compared with the existing version, which is exactly the second problem.",
    "Policy generation builds a policy from past access activity in CloudTrail. It does not review a policy that a developer has written, and the developer's own activity is not what the application needs."],
 ref:[], doc:"access-analyzer"},

{id:"q12-006", day:12, dom:1, tags:["IAM policies"],
 q:"A university department still manages 120 lab assistants as IAM users in one AWS account, all in the IAM group <code>LabAssistants</code>. Each assistant must be able to read and write only under a personal prefix, <code>home/&lt;user name&gt;/</code>, in a shared S3 bucket. Assistants join and leave every term, and the administrator does not want to write or edit a policy for each person. Which solution meets these requirements with the LEAST administrative effort?",
 o:["Attach an inline policy to each IAM user that names that user's own prefix in the resource ARN.",
    "Add a statement per assistant to the bucket policy that names the IAM user as principal and the user's prefix.",
    "Attach one policy to the group that allows the prefix <code>home/*</code>, and tag each user with a <code>prefix</code> tag.",
    "Attach one policy to the group whose resource ARN uses the policy variable <code>${aws:username}</code> for the prefix."],
 a:[3],
 x:["Per-user inline policies meet the access rule, but they are exactly the per-person policy writing that the administrator wants to avoid.",
    "This also works, but the bucket policy must be edited every time an assistant joins or leaves.",
    "<code>home/*</code> lets every assistant read and write every other assistant's prefix. A tag has no effect unless a policy condition or variable refers to it.",
    "When the policy is evaluated, <code>${aws:username}</code> is replaced with the name of the IAM user who makes the request, so one group policy confines every assistant to a personal prefix and new members need no policy change. The variable is available for IAM users, not for roles."],
 ref:[], doc:"iam-variables"},

{id:"q12-007", day:12, dom:1, tags:["IAM policies"],
 q:"A bank gives its database administrators access through an IAM role that has an AWS managed job-function policy attached. An internal audit objects for two reasons: the permissions of that policy change whenever AWS updates it, without passing the bank's change approval, and the bank cannot remove actions that the administrators never need. The auditors also want to be able to return to the previous set of permissions quickly if a change causes problems. Which solution meets these requirements?",
 o:["Keep the AWS managed policy, and attach a second AWS managed policy that grants read-only access to the databases.",
    "Copy the permissions into a customer managed policy, trim it, and attach it to the role in place of the AWS managed policy.",
    "Copy the permissions into an inline policy on the role, trim it, and detach the AWS managed policy from the role.",
    "Edit the AWS managed policy in the bank's account, and delete the statements that the administrators never use."],
 a:[1],
 x:["Allow policies only add up: a second policy removes nothing from the first, and AWS can still update both.",
    "The bank controls every change to a customer managed policy, and IAM keeps up to five versions of it, so an earlier version can be set as the default to roll back.",
    "An inline policy is under the bank's control too, but IAM does not version inline policies, so there is no earlier version to return to.",
    "Customers cannot change the permissions defined in an AWS managed policy. Only AWS updates them, and an update reaches every identity the policy is attached to."],
 ref:[], doc:"iam-managed-policies"},

{id:"q12-008", day:12, dom:1, tags:["IAM policies"],
 q:"A company's AWS CloudTrail trail delivers its log files to an S3 bucket. The bucket policy allows the CloudTrail service principal, <code>cloudtrail.amazonaws.com</code>, to call <code>s3:PutObject</code> on the bucket, with no conditions. A penetration tester shows that someone in an unrelated AWS account who knows the bucket name can configure a trail in their own account that delivers its log files into the company's bucket. The bucket must accept deliveries from CloudTrail only when the service acts for the company's own trail. What should a solutions architect do?",
 o:["Add a condition to the statement that requires <code>aws:SourceArn</code> to equal the ARN of the company's trail.",
    "Add a condition to the statement that requires <code>sts:ExternalId</code> to equal a value that the company generates.",
    "Replace the service principal in the statement with the company's own AWS account ID as the principal.",
    "Turn on S3 Versioning for the bucket so that log files from other accounts can be removed afterwards."],
 a:[0],
 x:["This is the cross-service confused deputy problem. AWS recommends <code>aws:SourceArn</code> or <code>aws:SourceAccount</code> wherever a service principal is granted access, so that the service can use the resource only on behalf of the expected resource or account.",
    "An external ID is checked in a role's trust policy when a third party calls <code>AssumeRole</code>. A service principal that writes to a bucket assumes no role and passes no external ID.",
    "CloudTrail delivers as its service principal, and the bucket policy authorizes that service principal. A statement that names only the account would no longer cover the delivery.",
    "Versioning keeps earlier versions of objects. It does not stop another account's trail from writing into the bucket."],
 ref:[], doc:"confused-deputy"},

{id:"q12-009", day:12, dom:1, tags:["IAM policies"],
 q:"A consulting firm's 40 analysts are IAM users in one AWS account. They belong to several IAM groups whose policies allow the Amazon S3, Amazon EC2 and Amazon RDS actions that their projects need. After an analyst's access key was used from an unknown network, the firm requires that the analysts' requests succeed only when they come from the firm's two office IP ranges. The analysts work only from the offices, and the existing group policies must not be rewritten. Which solution meets these requirements?",
 o:["Attach a policy to the analysts that allows all actions when <code>aws:SourceIp</code> is within the two office ranges.",
    "Add the two office ranges as the only inbound sources in the security groups of the analysts' resources.",
    "Attach a policy to the analysts that denies all actions when <code>aws:SourceIp</code> is not within the two office ranges.",
    "Enable MFA for every analyst, and require an MFA code whenever an analyst signs in to the console."],
 a:[2],
 x:["Allows only add up. The existing group policies would still allow the analysts' actions from any address, and this policy would additionally grant every action from the offices.",
    "Security groups control the network traffic that reaches the resources they are associated with, such as instances. They do not decide who may call AWS APIs with an access key.",
    "An explicit Deny overrides every Allow, so one added policy with a <code>NotIpAddress</code> condition on <code>aws:SourceIp</code> blocks requests from any other network without touching the group policies. The policy itself grants nothing.",
    "MFA makes a stolen password harder to use, but it does not restrict the network that a request comes from."],
 ref:["d4c1"], doc:"iam-policy-eval"},

// ---------- IAM roles and cross-account access ----------

{id:"q12-010", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"A company lets developers launch their own EC2 instances in a development account. A developer's IAM policy allows <code>ec2:RunInstances</code> and <code>iam:PassRole</code> on all resources. The account also contains a role, <code>DataAdmin</code>, that trusts Amazon EC2 and can read every S3 bucket. The security team notices that a developer could launch an instance with <code>DataAdmin</code> attached and use the instance to reach data that the developer's own policy does not allow. Developers must still be able to launch instances with the approved application roles, whose names start with <code>App-</code>. What should a solutions architect do?",
 o:["Add the developers as principals in the trust policy of each <code>App-</code> role, and leave them out of <code>DataAdmin</code>.",
    "Limit the <code>Resource</code> of the <code>iam:PassRole</code> statement to the ARNs of roles whose names start with <code>App-</code>.",
    "Tag the approved roles, and allow <code>iam:PassRole</code> only when an <code>aws:ResourceTag</code> condition matches the tag.",
    "Attach a permissions boundary to <code>DataAdmin</code> that takes away the role's access to the S3 buckets."],
 a:[1],
 x:["These roles trust Amazon EC2, because the instance assumes the role. Who may hand a role to EC2 is decided by <code>iam:PassRole</code> in the developer's policy, not by the trust policy.",
    "A service checks whether the caller has <code>iam:PassRole</code> for the role being handed over. Restricting the statement's Resource to the approved role ARNs lets developers pass only those roles, so an instance cannot get more permissions than intended.",
    "AWS warns against controlling who can pass a role with the ResourceTag condition key on <code>iam:PassRole</code>, because the results are not reliable. Scope the resource ARN instead.",
    "This would break <code>DataAdmin</code> for the workloads that need it, and developers could still pass any other powerful role in the account."],
 ref:["d4b2"], doc:"iam-passrole"},

{id:"q12-011", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"A startup sells a cost-optimization service. Each customer creates an IAM role in the customer's own AWS account that trusts the startup's AWS account, and gives the role ARN to the startup. The startup's backend then assumes the role to read the customer's usage data. A security consultant warns that a customer who learns or guesses another customer's role ARN could enter it in the startup's portal and see that customer's data. How should the startup design the integration to prevent this?",
 o:["Let each customer choose an external ID in the portal, and pass the chosen value on each <code>AssumeRole</code> call for that customer.",
    "Use one external ID for all customers, keep it confidential, and have customers require it in the role's trust policy.",
    "Ask each customer to require MFA in the role's trust policy with an <code>aws:MultiFactorAuthPresent</code> condition.",
    "Generate a unique external ID per customer, have customers require it in the trust policy, and pass it on each <code>AssumeRole</code> call."],
 a:[3],
 x:["The external ID must be controlled by the startup, not by its customers. If customers choose it, an attacker enters the victim's value together with the victim's role ARN.",
    "A shared value does not tell customers apart: the startup would send the same ID for every role, so another customer's role ARN still works.",
    "An MFA condition says how the caller authenticated, not which customer the startup is acting for, so the startup could still be tricked into using another customer's role.",
    "The startup generates an external ID that is unique among its customers and always sends the ID of the customer it is acting for. A role whose trust policy requires a different customer's ID cannot be assumed, which prevents the confused deputy problem."],
 ref:["d8c2"], doc:"confused-deputy"},

{id:"q12-012", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"An application runs on a fleet of 60 EC2 instances that all use the same IAM role through an instance profile. The role lets the application read from one S3 bucket. A new release must also send messages to an Amazon SQS queue. The instances hold in-memory sessions and must not be stopped or replaced for this change, and no access keys may be stored on them. What is the MOST operationally efficient way to give the application the new permission?",
 o:["Add a statement that allows the SQS actions to the permissions policy of the role that the instances already use.",
    "Create a second role with the SQS permission, and attach it to each instance alongside the existing role.",
    "Create an IAM user with the SQS permission, and place its access key in the application's configuration on each instance.",
    "Create a new role with both permissions, then stop each instance, swap its instance profile, and start it again."],
 a:[0],
 x:["When one role is used by many instances, a change to that role propagates automatically to all of them. Nothing has to be restarted or replaced.",
    "Only one role can be assigned to an EC2 instance at a time, and an instance profile can contain only one role.",
    "This stores long-term credentials on the instances, which the requirement forbids and which roles exist to avoid.",
    "Stopping the instances is ruled out, and it is unnecessary: the existing role can be changed while the instances run."],
 ref:["d4b2"], doc:"iam-roles-ec2"},

{id:"q12-013", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"During an access review, a security engineer finds a role named <code>AWSServiceRoleForRDS</code> in the company's AWS account. Nobody on the team remembers creating it, it trusts only Amazon RDS, and its permissions policy is broader than the engineer would like. The company runs several production RDS DB instances. The engineer wants to reduce the role's permissions or delete the role. What should the engineer conclude?",
 o:["It is a service role that an administrator created for RDS, so its permissions policy can be trimmed in IAM like that of any other role.",
    "It is the instance profile of the DB instances, so it can be swapped for a custom role with fewer permissions while the instances run.",
    "It is a service-linked role: RDS defines its permissions, which cannot be edited, and it can be deleted only after its related resources.",
    "It is a leftover from an AWS managed policy, so it can be detached from the DB instances and then deleted without any effect on them."],
 a:[2],
 x:["A service role that an administrator creates can be edited in IAM. This role is predefined by and linked to the service: an administrator can view its permissions but not edit them.",
    "Instance profiles pass roles to EC2 instances. This role is the one that Amazon RDS itself uses to call other AWS services on behalf of the DB instances.",
    "A service-linked role is predefined by the service with the permissions the service needs, and only that service can assume it. Amazon RDS does not allow editing <code>AWSServiceRoleForRDS</code>, and the role can be deleted only after its related resources are deleted.",
    "It is an IAM role, not a policy, and it is in use: Amazon RDS uses it to call AWS services on behalf of the DB instances."],
 ref:[], doc:"iam-slr"},

{id:"q12-014", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"A data team's nightly job runs for about three hours. An engineer starts it from a workstation with IAM user credentials: the script first assumes <code>PipelineRole</code> in a tooling account and then uses those credentials to assume <code>LoaderRole</code> in a data account, requesting a four-hour session for the second role. <code>LoaderRole</code> has a maximum session duration of 12 hours, and both trust policies and all permissions are correct. The second <code>AssumeRole</code> call fails. What should the engineer change so that the job can run to completion?",
 o:["Raise the maximum session duration of <code>PipelineRole</code> to 12 hours so that it covers the session of the second role.",
    "Request the four-hour session for <code>LoaderRole</code> with the <code>GetSessionToken</code> operation instead of <code>AssumeRole</code>.",
    "Add an external ID to the trust policy of <code>LoaderRole</code>, and pass the same value in the second call.",
    "Request a session of at most one hour for <code>LoaderRole</code>, and have the script repeat the role assumptions before it expires."],
 a:[3],
 x:["The one-hour limit on role chaining applies regardless of the maximum session duration that is configured on the individual roles.",
    "<code>GetSessionToken</code> returns temporary credentials for the existing IAM user. It does not assume <code>LoaderRole</code>.",
    "An external ID addresses the confused deputy problem with third parties. It has no effect on how long a session may last.",
    "Using one role's credentials to assume a second role is role chaining, and a chained session is limited to one hour: a request for a longer <code>DurationSeconds</code> fails. Requesting an hour or less and repeating the assumptions in time (the first role's credentials expire too) lets the job continue."],
 ref:["d4b3"], doc:"iam-roles"},

{id:"q12-015", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"A deployment role in Account B has a trust policy whose <code>Principal</code> is the ARN of the role <code>CiRunner</code> in Account A. Deployments have worked for a year. During a cleanup, an engineer in Account A deletes <code>CiRunner</code> and recreates it with the same name and the same policies. Since then, <code>CiRunner</code> gets AccessDenied when it tries to assume the deployment role, although nobody changed anything in Account B. What should a solutions architect do to restore access?",
 o:["Attach the <code>AdministratorAccess</code> policy to the recreated <code>CiRunner</code> role in Account A.",
    "Edit the deployment role's trust policy, and enter the ARN of <code>CiRunner</code> as the principal again.",
    "Wait until the temporary credentials that were issued to the old <code>CiRunner</code> role have expired.",
    "Add an external ID condition to the deployment role's trust policy, and pass the value from Account A."],
 a:[1],
 x:["Permissions in Account A are not the problem: the trusting account no longer recognizes the principal, and no identity-based policy in Account A changes the trust policy in Account B.",
    "When a trust policy is saved, a role ARN in its Principal element is transformed into that role's unique principal ID. The recreated role has a new ID that does not match the stored one, so the policy must be saved again with the ARN, which maps it to the new role.",
    "Time changes nothing here: the trust policy still holds the principal ID of the deleted role.",
    "An external ID adds a further condition. It does not re-establish which principal the role trusts."],
 ref:["d8c2"], doc:"iam-principal"},

{id:"q12-016", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"A manufacturer uses IAM Roles Anywhere so that on-premises servers obtain temporary AWS credentials with X.509 certificates from the company's private certificate authority, which is registered as a trust anchor. Certificates for servers in the finance department carry <code>OU=Finance</code> in their subject, and those for factory servers carry <code>OU=Factory</code>; one CA issues both. Today any server with a valid certificate can obtain credentials for the <code>FinanceReports</code> role. Only finance servers may use that role, and the company does not want to run a second certificate authority. Which solution meets these requirements?",
 o:["Create a second trust anchor that references the same CA certificate, and use it only for the finance servers.",
    "Attach a permissions boundary to <code>FinanceReports</code> that allows only the actions that the finance reports need.",
    "Add a condition on the certificate subject, such as <code>aws:PrincipalTag/x509Subject/OU</code>, to the role's trust policy.",
    "Store an IAM user access key for the finance team on the finance servers, and stop using Roles Anywhere on them."],
 a:[2],
 x:["Both trust anchors would accept every certificate that the one CA issues, so a factory server could authenticate through either of them.",
    "A boundary limits what the role can do, not who can obtain its credentials. Factory servers could still use the role.",
    "IAM Roles Anywhere maps fields of the authenticating certificate, such as the relative distinguished names of its subject, to principal tags on the session. AWS recommends conditions on them in the role's trust policy to restrict which certificates may assume the role.",
    "This brings back the long-term credentials that IAM Roles Anywhere is meant to remove from servers outside AWS."],
 ref:[], doc:"roles-anywhere"},

{id:"q12-017", day:12, dom:1, tags:["IAM roles & cross-account"],
 q:"A company's operations team works in a central operations account. The engineers must be able to stop, start and resize EC2 instances that belong to a separate workloads account, and the owner of the workloads account wants to define in one place exactly what the operations team may do there. No IAM users or long-term credentials may be created in the workloads account. Which solution meets these requirements?",
 o:["Attach a resource-based policy to each EC2 instance that names the operations account as the principal.",
    "Create an IAM group in the operations account whose policy allows the EC2 actions on the instances of the workloads account.",
    "Create IAM users for the engineers in the workloads account, and keep their access keys in the operations account.",
    "Create a role in the workloads account that allows the EC2 actions and trusts the operations account, and let the engineers assume it."],
 a:[3],
 x:["Amazon EC2 does not support resource-based policies, so there is nothing to attach to an instance. For such resources AWS says to use a role as a proxy.",
    "A cross-account request must be allowed in both accounts. An identity-based policy in the operations account alone is not enough, and EC2 has no resource-based policy that could provide the other half.",
    "This creates exactly the IAM users and long-term credentials in the workloads account that the requirement rules out.",
    "A cross-account role delegates access to resources that do not support resource-based policies: its permissions policy in the workloads account defines what is allowed, its trust policy names the operations account, and engineers receive temporary credentials when they assume it."],
 ref:["d8c2","d4b3"], doc:"iam-cross-account"},

// ---------- IAM Identity Center, federation, Directory Service ----------

{id:"q12-018", day:12, dom:1, tags:["IAM Identity Center & federation"],
 q:"A company with 900 employees enabled IAM Identity Center and connected its external SAML 2.0 identity provider as the identity source. Sign-in works, but administrators still create every user and group by hand in Identity Center before they can assign access, and employees who leave the company stay in Identity Center until someone removes them. The company wants the users and groups in Identity Center to follow the identity provider without manual work. What should a solutions architect do?",
 o:["Enable automatic provisioning in IAM Identity Center, and configure the identity provider to synchronize users and groups with SCIM.",
    "Change the identity source to the Identity Center directory, and load the users from an export file every night.",
    "Create an IAM SAML identity provider in every member account, and map the provider's groups to IAM roles there.",
    "Add the identity provider as a second identity source so that IAM Identity Center can query it for users and groups."],
 a:[0],
 x:["SAML gives Identity Center no way to look up users and groups in the provider, so they must be provisioned. Automatic provisioning synchronizes them from the provider with the SCIM v2.0 protocol; the provider controls how often it sends changes and how departures are handled.",
    "With the Identity Center directory as the source, users and groups are created and managed in Identity Center itself, which means more manual work, not less.",
    "Federation with IAM in each account repeats the configuration per account and gives up the central assignments of Identity Center. It does not solve provisioning.",
    "An organization can have only one identity source in IAM Identity Center, and the SAML protocol offers no way to query a provider for its users and groups."],
 ref:[], doc:"identity-center"},

{id:"q12-019", day:12, dom:1, tags:["IAM Identity Center & federation"],
 q:"A company uses IAM Identity Center with the 45 accounts of its organization. Its data engineers get access through a permission set that contains one AWS managed policy. The engineers now need an additional custom set of permissions that no AWS managed policy provides, identical in all 45 accounts and in every account that is assigned later. The cloud team wants to maintain these permissions in one place and does not want to deploy anything to the member accounts itself. Which solution meets these requirements with the LEAST operational overhead?",
 o:["Reference a customer managed policy by name in the permission set, and create that policy in each of the accounts.",
    "Add the custom permissions as an inline policy to the permission set that the engineers already use.",
    "Edit the <code>AWSReservedSSO_</code> role of the permission set in each account, and attach the permissions to it.",
    "Create an IAM user for each engineer in each account, and attach the custom permissions to those users."],
 a:[1],
 x:["With a customer managed policy, the policy must exist in every account before the permission set is assigned, so the cloud team would have to create and maintain it in all 45 accounts.",
    "An inline policy is part of the permission set: Identity Center creates it in every account where the permission set is assigned and attaches it to the role there, so the permissions are maintained in one place.",
    "IAM Identity Center manages these roles and keeps them in line with the permission set, so changes belong in the permission set. Editing 45 roles by hand is also the work the team wants to avoid.",
    "IAM users multiply identities and long-term credentials in every account, which is what Identity Center replaces."],
 ref:[], doc:"identity-center"},

{id:"q12-020", day:12, dom:1, tags:["IAM Identity Center & federation"],
 q:"A research institute has a single standalone AWS account and does not plan to use AWS Organizations or IAM Identity Center. Its 80 scientists already sign in to a SAML 2.0 identity provider that the institute runs. They need access to the AWS Management Console with permissions that depend on their group in the identity provider, and the institute does not want to create or maintain IAM users. Which combination of steps meets these requirements? (Choose two.)",
 o:["Create an IAM user for each scientist with the same user name as in the identity provider, and require MFA.",
    "Create a SAML identity provider in IAM from the metadata document of the institute's identity provider.",
    "Create an Amazon Cognito user pool, add the institute's identity provider, and send scientists to its sign-in page.",
    "Create IAM roles that trust the SAML provider, and map the groups to these roles in the identity provider's assertions.",
    "Create an IAM OIDC identity provider for the institute, and have scientists call <code>AssumeRoleWithWebIdentity</code>."],
 a:[1,3],
 x:["This duplicates every identity in IAM and creates the users that the institute wants to avoid.",
    "IAM supports SAML 2.0 federation for a single account without IAM Identity Center. The SAML provider entity in IAM establishes trust with the institute's identity provider.",
    "A user pool signs users in to your own web and mobile apps and issues tokens to those apps. It is not the way into the AWS Management Console.",
    "Federated users receive a console session for an IAM role whose trust policy names the SAML provider. In the identity provider, assertions map users or groups to the roles, so permissions follow the group.",
    "The institute's provider speaks SAML 2.0. OIDC federation in IAM is for OpenID Connect compatible providers, such as GitHub Actions."],
 ref:[], doc:"iam-federation"},

{id:"q12-021", day:12, dom:1, tags:["IAM Identity Center & federation"],
 q:"A company builds its website with GitHub Actions workflows that run outside AWS. The deployment job uploads each new version of the site to an S3 bucket. Today the workflows use an IAM user access key that is stored as a repository secret, which an audit flagged. The security team requires that no long-term AWS credentials exist outside AWS and that only workflows from the company's own repository can obtain access. Which solution meets these requirements?",
 o:["Keep the IAM user, rotate its access key every day with a scheduled job, and update the repository secret each time.",
    "Create a role that trusts the company's AWS account, and store the role's ARN as a repository secret for the workflows.",
    "Add GitHub's OIDC provider to IAM, and create a role whose trust policy limits the token's <code>sub</code> claim to the company's repository.",
    "Register GitHub as a trust anchor in IAM Roles Anywhere, and let the workflows request credentials from it."],
 a:[2],
 x:["Daily rotation shortens the life of each key, but a long-term credential still sits outside AWS at all times.",
    "A role ARN is not a credential. The workflow would still need AWS credentials from somewhere to call <code>AssumeRole</code>, so the access key would have to stay.",
    "With OIDC federation the workflow exchanges the token that GitHub issues for temporary credentials of an IAM role, so no access key is stored. A condition on <code>token.actions.githubusercontent.com:sub</code> limits the role to the company's organization and repository.",
    "IAM Roles Anywhere authenticates workloads with X.509 certificates from a certificate authority that you register as a trust anchor, and certificates from public CAs cannot be used. GitHub Actions already issues OIDC tokens that IAM can trust."],
 ref:[], doc:"iam-federation"},

{id:"q12-022", day:12, dom:1, tags:["IAM Identity Center & federation"],
 q:"A company is moving a .NET application and its database to AWS. The database will run on Amazon RDS for SQL Server, and the application must connect to it with Windows Authentication. Employees must keep signing in with their existing accounts in the company's on-premises Active Directory, which stays the source of user identities; the company does not want a second set of user accounts in AWS. The on-premises network is already connected to the VPC. Which directory solution meets these requirements?",
 o:["AD Connector that forwards authentication requests to the on-premises domain controllers",
    "Simple AD with the employees' accounts created again in the new directory",
    "An Amazon Cognito user pool that federates to the on-premises Active Directory",
    "AWS Managed Microsoft AD with a trust relationship to the on-premises Active Directory"],
 a:[3],
 x:["AD Connector is a proxy to the on-premises directory for compatible AWS applications, but it is not compatible with RDS for SQL Server.",
    "Simple AD does not support trust relationships and is not compatible with RDS for SQL Server. It would also mean a second set of accounts.",
    "A Cognito user pool is a directory for the users of web and mobile apps. It is not an Active Directory domain that SQL Server can use for Windows Authentication.",
    "RDS for SQL Server uses AWS Managed Microsoft AD for Windows Authentication, and a forest trust lets users from the on-premises Active Directory authenticate, so the identities stay where they are."],
 ref:[], doc:"directory"},

{id:"q12-023", day:12, dom:1, tags:["IAM Identity Center & federation"],
 q:"A company uses IAM Identity Center with an external SAML 2.0 identity provider as its identity source. Employees sign in at the provider and then reach the AWS access portal. After a phishing incident, the security team requires a second authentication factor every time an employee signs in to reach AWS accounts. Where should the company enforce this requirement?",
 o:["In the IAM Identity Center authentication settings, by turning on MFA for all users of the access portal",
    "In the sign-in policy of the external identity provider, by requiring MFA for the connection to AWS",
    "In IAM in every member account, by registering a virtual MFA device for each employee",
    "In every permission set, by shortening the session duration to the minimum of one hour"],
 a:[1],
 x:["MFA in IAM Identity Center is not supported for external identity providers. It applies when the identity source is the Identity Center directory or Active Directory.",
    "With an external SAML 2.0 provider as the identity source, the provider authenticates the users, so its own multi-factor authentication is what protects sign-in. Identity Center holds no passwords or MFA devices for these users.",
    "IAM Identity Center does not create IAM users in the accounts: employees enter through roles, so there is no IAM user to register a device for.",
    "A shorter session limits how long credentials stay valid. It adds no second factor at sign-in."],
 ref:[], doc:"identity-center"},

// ---------- Root user and MFA, shared responsibility ----------

{id:"q12-024", day:12, dom:1, tags:["Root user & MFA"],
 q:"Three people administer a company's standalone AWS account. The root user has one hardware TOTP token as its only MFA device, kept in the office safe. The security lead sees two risks: the token is the single way to pass MFA for the root user, so losing or breaking it would lock the team out until the account is recovered, and one-time codes can be captured by a phishing site. The root user must stay protected by MFA. Which combination of actions addresses both risks? (Choose two.)",
 o:["Register more than one MFA device for the root user, and keep the devices in separate secure places.",
    "Create a root user access key, and keep it in a password manager as a second way into the account.",
    "Use FIDO security keys or passkeys as the root user's MFA devices instead of one-time codes.",
    "Move the one-time codes to an authenticator app on the phone of one of the administrators.",
    "Remove MFA from the root user, and split a long random password between two administrators."],
 a:[0,2],
 x:["The root user can register up to eight MFA devices, and AWS recommends more than one so that a lost or broken device does not interrupt access.",
    "AWS advises against root user access keys. A key would also be a way into the account that skips the MFA the requirement keeps.",
    "Passkeys and security keys are FIDO-based and resistant to phishing, which is why AWS recommends them over TOTP-based options.",
    "An authenticator app still produces one-time codes that a phishing site can capture, and it is still a single device.",
    "The root user must stay protected by MFA, and AWS requires MFA for the root user of every account type."],
 ref:[], doc:"iam-mfa"},

{id:"q12-025", day:12, dom:1, tags:["Shared responsibility"],
 q:"A company runs its order system on Amazon EC2 and is preparing a security audit. The auditor asks the company to sort four IT controls by who is responsible for them under the AWS shared responsibility model: physical protection of the data centers, patch management, security awareness training, and the placement of the company's data into separate network zones. Which statements are correct? (Choose two.)",
 o:["Patch management is fully inherited from AWS on EC2, so the company only keeps its own application code up to date.",
    "Physical and environmental controls are inherited controls: the company inherits them fully from AWS.",
    "Zoning of the company's data is an AWS control, because AWS operates the network on which the VPCs are built.",
    "Awareness training is inherited from AWS, because AWS already trains the staff who run the infrastructure.",
    "Patch management is a shared control: AWS patches the infrastructure, and the company patches its guest OS and applications."],
 a:[1,4],
 x:["On EC2 the customer is responsible for patching the guest operating system and applications. AWS patches and fixes flaws within the infrastructure.",
    "Inherited controls are those a customer fully inherits from AWS, and physical and environmental controls are the example AWS gives.",
    "Routing or zoning data within specific security environments is a customer-specific control, solely the customer's responsibility.",
    "Awareness and training is a shared control: AWS trains AWS employees, and the customer must train its own employees.",
    "Shared controls apply to both layers in separate contexts. For patch management, AWS covers the infrastructure and the customer covers its guest OS and applications."],
 ref:[], doc:"shared"},

// ---------- AWS Organizations: SCPs, RCPs, AWS RAM ----------

{id:"q12-026", day:12, dom:1, tags:["Organizations & SCPs"],
 q:"A company's organization has the default <code>FullAWSAccess</code> SCP attached to the root. To restrict its research accounts, an administrator replaced <code>FullAWSAccess</code> on the Research OU with an SCP that allows only Amazon EC2 and Amazon S3 actions. The Genomics OU, which is nested under Research, must also use Amazon DynamoDB, so the administrator attached an SCP that allows DynamoDB actions directly to the Genomics OU, which still has <code>FullAWSAccess</code> as well. Users with the <code>AdministratorAccess</code> policy in a Genomics account still cannot use DynamoDB. What is the reason?",
 o:["An action must be allowed by an SCP at every level from the root down to the account, and the Research OU does not allow DynamoDB.",
    "The SCP on the Genomics OU does not grant permissions, so the users also need an IAM policy that allows DynamoDB actions.",
    "SCPs take effect only for IAM users, and these administrators sign in to the Genomics account through IAM roles.",
    "An SCP that is attached to a nested OU is ignored whenever its parent OU has a custom SCP of its own."],
 a:[0],
 x:["For a permission to be allowed in an account, there must be an explicit Allow at every level from the root through each OU in the path to the account. Research allows only EC2 and S3, so nothing attached below it can bring DynamoDB back.",
    "SCPs indeed grant nothing, but these users already have <code>AdministratorAccess</code>. The action is blocked by the guardrail above them.",
    "SCPs limit both the IAM users and the IAM roles of member accounts, including the root user.",
    "SCPs on nested OUs are evaluated, not ignored: the effective permissions are what every level allows, and a Deny at any level also applies."],
 ref:["d4c2"], doc:"scp"},

{id:"q12-027", day:12, dom:1, tags:["Organizations & SCPs"],
 q:"A company attaches an SCP to its Production OU that denies <code>ec2:TerminateInstances</code> for every principal, to stop engineers from terminating production instances by hand. The engineers confirm that they are blocked. A week later, an auditor sees in the logs that instances in a production account were terminated during a scale-in by Amazon EC2 Auto Scaling, which acted through its service-linked role, and asks whether the SCP is broken. What should the security team answer?",
 o:["The SCP is misconfigured: it must be attached to each account, because SCPs on an OU cover only IAM users.",
    "The SCP was bypassed: Auto Scaling acted as the account's root user, which SCPs never restrict in member accounts.",
    "The SCP works as designed: SCPs do not restrict actions that are performed with a service-linked role.",
    "The SCP is incomplete: it needs an Allow statement for Auto Scaling ahead of its Deny statement."],
 a:[2],
 x:["An SCP attached to an OU applies to all accounts under it, and it affects IAM users and roles alike.",
    "SCPs do restrict the root user of member accounts. The terminations were made with a service-linked role, not as the root user.",
    "SCPs do not affect any service-linked role: actions performed with the permissions of a service-linked role are among the things an SCP cannot restrict. The engineers remain blocked, which was the purpose.",
    "An explicit Deny cannot be overridden by an Allow, and no Allow is needed here: the service-linked role is simply outside the reach of SCPs."],
 ref:["d4c2"], doc:"scp"},

{id:"q12-028", day:12, dom:1, tags:["Organizations & SCPs"],
 q:"A company has 200 accounts in AWS Organizations. Developers in member accounts write their own S3 bucket policies and Secrets Manager resource policies, and a review found several that grant access to AWS accounts outside the organization. An SCP already limits what the company's own identities can do. The security team needs a central control that stops principals outside the organization from accessing these resources in any member account, whatever the resource policies say, including in accounts that are created later. Which solution meets these requirements with the LEAST operational overhead?",
 o:["Attach a service control policy (SCP) to the root that denies access to principals whose <code>aws:PrincipalOrgID</code> is not the organization's.",
    "Create an IAM Access Analyzer external access analyzer for the organization, and review its findings every week.",
    "Deploy a matching Deny statement into the policy of every bucket and every secret with an automation script.",
    "Attach a resource control policy (RCP) to the root that denies access to principals whose <code>aws:PrincipalOrgID</code> is not the organization's."],
 a:[3],
 x:["SCPs limit the principals of the organization's own member accounts. They do not affect users or roles from accounts outside the organization.",
    "The analyzer reports resources that are shared outside the zone of trust, which is useful before the control is introduced, but it detects and does not prevent.",
    "This must reach every existing and future resource, and the developers who write the resource policies could remove the statement again.",
    "RCPs are resource-centric guardrails: attached to the root, they limit what any principal, including one outside the organization, can do with supported resources such as S3 buckets and Secrets Manager secrets in every member account. Resources in the management account are not covered, and the policy needs exceptions for the AWS services that must reach the resources."],
 ref:[], doc:"rcp"},

{id:"q12-029", day:12, dom:1, tags:["Organizations & SCPs","VPC peering & Transit Gateway"],
 q:"A company's network team owns a transit gateway in a central networking account. Thirty application accounts in the Workloads OU of the company's organization must attach their VPCs to it, and new accounts are added to that OU every month. The network team does not want to keep a list of account IDs or wait for each account to accept an invitation. Which solution meets these requirements with the LEAST operational overhead?",
 o:["Create a resource share in AWS RAM that lists every account ID, and add each new account when it is created.",
    "Enable sharing with AWS Organizations in AWS RAM, and share the transit gateway with the Workloads OU.",
    "Create a transit gateway in every application account, and peer each of them with the central transit gateway.",
    "Create a cross-account IAM role in the networking account that each application account assumes to attach its VPC."],
 a:[1],
 x:["This works, but it is the list of account IDs that the team wants to avoid, and every new account means another change.",
    "With sharing in the organization enabled, AWS RAM shares with an OU without listing accounts and without invitations, and an account that is added to the OU gets access to the resource share automatically.",
    "This multiplies the gateways and peerings to run instead of sharing the one that the network team already manages.",
    "A role would let other accounts act inside the networking account, but the VPCs to attach belong to the application accounts. Sharing through AWS RAM is how other accounts use a centrally owned transit gateway."],
 ref:[], doc:"ram"},

// ---------- Amazon Cognito ----------

{id:"q12-030", day:12, dom:1, tags:["Cognito"],
 q:"A software company sells a web application to business customers. Employees of each customer must sign in with their own company's SAML 2.0 identity provider, while individual users without a corporate identity provider sign up with an email address and a password. The application's backend should receive the same kind of token for every user, whichever way the user signed in, and the company does not want to build or operate its own authentication service. Which solution meets these requirements?",
 o:["Enable IAM Identity Center, connect the customers' identity providers, and assign the customers' employees to the application.",
    "Create an IAM SAML identity provider for each customer, and give each customer's employees an IAM role to sign in with.",
    "Create an Amazon Cognito user pool, add each customer's SAML provider to it, and use the user pool's tokens in the backend.",
    "Create a Cognito identity pool, add each customer's SAML provider to it, and use the temporary AWS credentials in the backend."],
 a:[2],
 x:["IAM Identity Center connects a company's own workforce to AWS accounts and applications and has one identity source per organization. It is not a sign-up and sign-in directory for an application's customers.",
    "Federation with IAM gives access to AWS resources and the console. It offers no sign-up, no user directory and no tokens for the application's own backend.",
    "A user pool is a user directory that signs up local users and federates to social, SAML and OIDC providers. It issues one standard set of JSON web tokens for all of them, so the backend handles a single token format.",
    "An identity pool exchanges a trusted token for temporary AWS credentials to call AWS services. It does not sign users up or issue the tokens that the application's backend verifies."],
 ref:[], doc:"cognito"},

{id:"q12-031", day:12, dom:1, tags:["Cognito"],
 q:"A travel company's mobile app lets anyone browse offers before creating an account. While browsing, the app must read images directly from one private S3 bucket. Users who sign in later get broader access through a different IAM role. The company must not embed AWS access keys in the app, does not want to make the bucket public, and wants visitors who have not signed in to receive only the minimum permissions. Which solution meets these requirements?",
 o:["Enable guest access in an Amazon Cognito identity pool, and give the role for unauthenticated identities read access to that bucket only.",
    "Create an Amazon Cognito user pool, and let the app sign in every visitor with one shared guest user name and password.",
    "Create an IAM user with read access to the bucket, and ship its access key in an encrypted file inside the app.",
    "Add a bucket policy that allows <code>s3:GetObject</code> for all principals when <code>aws:UserAgent</code> matches the app."],
 a:[0],
 x:["An identity pool can issue temporary, limited-privilege AWS credentials to guests who have not signed in, through a separate IAM role for unauthenticated identities, and it uses a different role for authenticated users.",
    "A shared password inside the app is an embedded credential, and user pool tokens alone are not AWS credentials for Amazon S3.",
    "Anything shipped inside the app can be extracted, and this is the embedded long-term access key that the company rules out.",
    "This makes the bucket public, and AWS warns that <code>aws:UserAgent</code> is supplied by the caller and should not be used to keep unauthorized parties out."],
 ref:[], doc:"cognito"},

{id:"q12-032", day:12, dom:1, tags:["Cognito"],
 q:"A media company's web app signs users in with an Amazon Cognito user pool and obtains temporary AWS credentials through a Cognito identity pool. All signed-in users currently receive the same IAM role, which allows read access to the content bucket. The company is adding an editors tier: only users in the user pool group <code>Editors</code> may upload to the bucket, while all other users stay read-only. AWS must enforce the difference, not application code. Which combination of steps meets these requirements with the LEAST development effort? (Choose two.)",
 o:["Give the authenticated role upload permissions, and hide the upload button in the app for users outside the group.",
    "Assign an IAM role that allows uploads to the <code>Editors</code> group in the user pool.",
    "Create a second identity pool for editors, and have the app decide which identity pool to call after sign-in.",
    "Create an IAM user for each editor, and have the app use that user's access key for uploads.",
    "Configure the identity pool to choose the role from the user pool token instead of always using the default role."],
 a:[1,4],
 x:["Every signed-in user's credentials could then upload, whatever the app shows. The difference would exist only in application code.",
    "A user pool group can have an IAM role. The role then appears in the ID token of the group's members, in the <code>cognito:roles</code> and <code>cognito:preferred_role</code> claims.",
    "This makes the application code decide who is an editor, which the company wants to avoid. One identity pool can assign different roles.",
    "IAM users bring long-term access keys into a web app, which is what the identity pool's temporary credentials replace.",
    "With role selection from the token, the identity pool gives members of the group the group's role and everyone else the default authenticated role, so IAM enforces the difference."],
 ref:[], doc:"cognito"},

// ---------- Secrets Manager and Parameter Store ----------

{id:"q12-033", day:12, dom:2, tags:["Secrets Manager & Parameter Store"],
 q:"An order-processing application reads its Amazon RDS for PostgreSQL credentials from AWS Secrets Manager and opens new database connections continuously. The secret is rotated every 30 days by a Lambda rotation function that uses the single-user strategy. During each rotation, a few requests fail with authentication errors in the short interval between the password change in the database and the update of the secret. The application must stay available during rotation, and the credentials must keep rotating automatically. Which solution meets these requirements?",
 o:["Lengthen the rotation interval of the secret from 30 days to 365 days, and keep the single-user strategy.",
    "Replicate the secret to a second Region, and have the application read the replica during each rotation.",
    "Store the password in a Parameter Store SecureString parameter, and update it with a scheduled script.",
    "Switch the secret to the alternating users rotation strategy, with a superuser secret for the rotation function."],
 a:[3],
 x:["Fewer rotations mean fewer incidents, but every rotation still has the same interval in which requests can fail.",
    "A replica is a copy of the primary secret: the rotated value propagates to it, so it offers no second valid set of credentials.",
    "Parameter Store has no credential rotation. A script would be custom tooling with the same gap between the two updates.",
    "The alternating users strategy updates the password of a second, cloned user on each rotation, so an application that retrieves the secret during rotation still gets valid credentials. AWS describes it as appropriate for applications that require high availability; it needs a superuser's credentials in another secret to clone the user."],
 ref:[], doc:"secrets-rotation"},

{id:"q12-034", day:12, dom:1, tags:["Secrets Manager & Parameter Store","VPC endpoints & PrivateLink"],
 q:"A payment application runs on EC2 instances in private subnets and reads an API signing secret from AWS Secrets Manager through an interface VPC endpoint. Several IAM roles in the account are allowed to read the secret. After a developer retrieved the secret value from a laptop with one of those roles, the security team requires that the secret value can be retrieved only by requests that arrive through the application's VPC endpoint, whichever role is used. Which solution meets this requirement?",
 o:["Attach a resource policy to the secret that denies <code>secretsmanager:GetSecretValue</code> unless <code>aws:SourceIp</code> is in the private subnets' CIDR range.",
    "Attach a resource policy to the secret that denies <code>secretsmanager:GetSecretValue</code> unless <code>aws:SourceVpce</code> is the endpoint's ID.",
    "Restrict the security group of the VPC endpoint so that only the application's subnets can connect to the endpoint.",
    "Encrypt the secret with a customer managed KMS key, and turn on automatic rotation of the secret every 30 days."],
 a:[1],
 x:["<code>aws:SourceIp</code> can be used only for public IP address ranges, and the key is not available at all when a request comes through a VPC endpoint.",
    "A Deny in the secret's resource policy for requests whose <code>aws:SourceVpce</code> is not the endpoint's ID applies to every role, because an explicit Deny overrides any Allow. Requests that other AWS services make for the secret must then come through the VPC as well.",
    "This controls who can use the endpoint. A permitted role outside the VPC can still retrieve the secret through the public Secrets Manager endpoint.",
    "Encryption and rotation protect the stored value and limit its lifetime. They do not restrict the network path of a request from a permitted role."],
 ref:[], doc:"secrets"},

{id:"q12-035", day:12, dom:4, tags:["Secrets Manager & Parameter Store"],
 q:"A logistics company runs 25 Lambda functions per environment. The functions share about 60 static, non-secret settings such as endpoint URLs, queue names and table names, which change a few times a year and must be organized per environment so that a production function's role can read only the values under <code>/prod/</code>. The functions also use one database password, which must be rotated automatically. The team wants managed services, no redeployment when a value changes, and no staged rollouts. Which combination of actions meets these requirements MOST cost-effectively? (Choose two.)",
 o:["Store the settings as standard-tier String parameters in Parameter Store under a path per environment.",
    "Store each setting as its own secret in AWS Secrets Manager with a name prefix per environment.",
    "Store the settings in an AWS AppConfig configuration profile, and deploy each change with a deployment strategy.",
    "Store the database password in AWS Secrets Manager, and turn on automatic rotation for the secret.",
    "Store the database password in a Parameter Store SecureString parameter, and change it with a scheduled script."],
 a:[0,3],
 x:["Parameter Store is the store AWS recommends for static configuration such as endpoint URLs and resource identifiers. Hierarchies group parameters by path, an IAM policy can let a role read only <code>/prod/*</code>, and the standard tier is free.",
    "Secrets Manager is built for credentials and is billed per secret per month and per API call. These 60 values are not secrets and need no rotation.",
    "AppConfig is for frequently changed configuration that needs validation, gradual rollout and automatic rollback, and it is billed per configuration request. That is more than static settings need.",
    "Secrets Manager rotates credentials automatically with native database integrations, and AWS recommends it for secrets such as database credentials.",
    "Parameter Store has no credential rotation, so the script would be custom tooling to build and run."],
 ref:[], doc:"parameter-store"},

// ---------- KMS and CloudHSM ----------

{id:"q12-036", day:12, dom:1, tags:["KMS & encryption"],
 q:"An insurer encrypts its S3 buckets and EBS volumes with server-side encryption that uses AWS KMS keys, and it wants to keep these service integrations and its key policies. A new regulation explicitly requires that the key material for these keys be generated and stored in single-tenant hardware security modules that the insurer controls, and that the insurer be able to cut off all use of the keys on its own at any time. Which solution meets these requirements?",
 o:["Create an AWS CloudHSM cluster, and configure Amazon S3 and Amazon EBS to request their encryption keys from the cluster directly.",
    "Create KMS keys without key material, and import key material that the insurer generates in its own on-premises HSMs.",
    "Create an AWS CloudHSM cluster, connect it to AWS KMS as a custom key store, and create the KMS keys in that key store.",
    "Create customer managed KMS keys in the standard key store, and turn on automatic rotation with the shortest period."],
 a:[2],
 x:["AWS services integrate with AWS KMS, not directly with CloudHSM. KMS in turn reaches a CloudHSM cluster through the custom key store feature.",
    "Imported key material gives control over how the material is generated and when it expires, but in AWS it lives in the standard KMS key store, a fleet of HSMs that is not dedicated to one customer.",
    "An AWS CloudHSM key store is a KMS custom key store backed by a cluster that the customer owns and manages: the key material is generated and kept in that single-tenant cluster, the keys work with AWS services that support customer managed keys, and while the key store is disconnected nobody can use its keys. (The other custom key store type, an external key store, keeps the keys in an HSM outside AWS.)",
    "Rotation changes the key material over time, not where it is kept: the standard key store uses the HSM fleet that AWS KMS operates for all customers."],
 ref:[], doc:"kms"},

{id:"q12-037", day:12, dom:1, tags:["KMS & encryption"],
 q:"A company's batch platform starts a short-lived worker role for each analytics job. During the job the worker must decrypt data with one customer managed KMS key, and when the job ends that permission must disappear. Hundreds of jobs start and finish every day. The security team does not want the platform to edit the key policy or IAM policies for every job, and each job's permission must be removable on its own. Which solution meets these requirements?",
 o:["Have the platform add each worker to the key policy when its job starts, and remove the worker when the job ends.",
    "Allow <code>kms:Decrypt</code> on the key for all workers in one IAM policy, and disable the key between jobs.",
    "Create a new KMS key for each job, re-encrypt the data under it, and schedule the key for deletion afterwards.",
    "Have the platform create a KMS grant on the key for each worker, and retire or revoke the grant when the job ends."],
 a:[3],
 x:["This edits the key policy hundreds of times a day, which the security team rules out.",
    "Every worker would hold the permission all the time, and a disabled key stops all jobs at once, so no job's permission is removable on its own.",
    "Re-encrypting the data for every job is far more work than the task needs, and it leaves hundreds of keys to track.",
    "Grants are often used for temporary permissions: one is created for a grantee principal on exactly one KMS key, used, and then deleted by retiring or revoking it, without any change to key policies or IAM policies."],
 ref:[], doc:"kms-grants"},

// ---------- Network Firewall and Firewall Manager ----------

{id:"q12-038", day:12, dom:1, tags:["WAF, Shield & Firewall Manager"],
 q:"A company's VPC hosts application servers that reach the internet through a NAT gateway. Amazon GuardDuty has twice reported servers that contacted known malicious hosts, each time after the traffic had already left the VPC. The security team now requires a managed control in the traffic path that blocks such connections instead of only reporting them, uses threat rules that AWS keeps current, and recognizes a protocol such as TLS by inspecting the traffic, whichever port a server uses. Which solution meets these requirements?",
 o:["Deploy AWS Network Firewall with AWS managed stateful rule groups, and route the VPC's outbound traffic through it.",
    "Add deny rules for the reported IP addresses to the network ACLs of the private subnets after each finding.",
    "Enable every GuardDuty protection plan in the account, and send all findings to the security team by email.",
    "Subscribe to AWS Shield Advanced, and add the NAT gateway's Elastic IP address as a protected resource."],
 a:[0],
 x:["Network Firewall is a managed, stateful network firewall and intrusion prevention service that filters traffic at the perimeter of a VPC, including traffic to a NAT gateway. It offers AWS managed domain, IP and threat signature rule groups, and its stateful protocol detection filters protocols independent of the port used.",
    "A network ACL allows or denies traffic by rule at the subnet level and is stateless. Adding addresses by hand after each finding always comes after the fact, and a network ACL does not identify protocols inside the traffic.",
    "GuardDuty is a threat detection service: it identifies suspicious activity and reports it. More findings are still reports, not a control in the traffic path.",
    "Shield Advanced protects resources against DDoS attacks from outside. It does not filter the connections that the servers open to the internet."],
 ref:[], doc:"network-firewall"},

{id:"q12-039", day:12, dom:1, tags:["WAF, Shield & Firewall Manager"],
 q:"A company has 150 accounts in AWS Organizations, and teams create their own security groups. Audits keep finding security groups that allow SSH from <code>0.0.0.0/0</code>. The security team wants one centrally managed control that continuously finds security group rules that violate the company's standard in every account, including accounts that join later, and that can remove the offending rules automatically. Which solution meets these requirements with the LEAST operational overhead?",
 o:["Create an AWS WAF web ACL in each account with a rule that blocks SSH requests from the internet.",
    "Subscribe every account to AWS Shield Advanced, and add the instances as protected resources.",
    "Create an AWS Firewall Manager security group audit policy for the organization, with automatic remediation.",
    "Deploy a custom AWS Config rule with a remediation function to each account, and repeat this for new accounts."],
 a:[2],
 x:["AWS WAF inspects HTTP(S) requests to protected web resources. It does not see SSH traffic and does not manage security groups.",
    "Shield Advanced protects against DDoS attacks. It does not review or change security group rules.",
    "Firewall Manager security group policies audit security group rules across the organization to locate and remediate noncompliant rules, and Firewall Manager applies its policies automatically to accounts and resources as they are added.",
    "This can find and fix the rules, but the team has to build it, deploy it to 150 accounts and repeat that for each new one. Firewall Manager does this centrally."],
 ref:[], doc:"firewall-manager"},

// ---------- Threat detection and compliance services ----------

{id:"q12-040", day:12, dom:1, tags:["Threat detection"],
 q:"A payment company stores cardholder data on AWS. For its next assessment, the company must show that its own AWS resources, across all of its accounts, are configured in line with PCI DSS. It wants every failed check listed as a finding and the results tracked continuously instead of once a year. The compliance reports about AWS's own infrastructure are already on file. Which solution meets these requirements?",
 o:["Download the current PCI DSS reports from AWS Artifact, and attach them to the assessment every quarter.",
    "Enable the PCI DSS standard in AWS Security Hub CSPM, and work through the control findings it generates.",
    "Enable Amazon Detective, and use its behavior graph to list the resources that fail the PCI DSS checks.",
    "Enable Amazon GuardDuty in every account, and treat each GuardDuty finding as a failed PCI DSS check."],
 a:[1],
 x:["AWS Artifact provides AWS's own security and compliance documents. Customers remain responsible for demonstrating the compliance of what they run, and those reports are already on file.",
    "Security Hub CSPM (the posture-check part of what the exam guide calls AWS Security Hub) runs automated checks against the controls of standards such as PCI DSS and generates control findings across accounts. The checks help to assess compliance; they do not guarantee it.",
    "Detective helps to investigate the root cause of security findings and suspicious activity from log data. It does not run configuration checks against a standard.",
    "GuardDuty is a threat detection service that identifies suspicious and potentially malicious activity. Its findings are not checks of resource configuration against PCI DSS."],
 ref:[], doc:"securityhub"}

);
